#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# Acrobot Evaluation Script: Cross-Validation (Seed 106 Pool)
# Task: Evaluate 5 Champions on 100 New Environments generated by Seed 106

import os
import argparse
import random
import multiprocessing as mp
from multiprocessing.connection import Client
from typing import Optional, List, Dict
import numpy as np
import torch
import torch.nn as nn
import gymnasium as gym
from tqdm import tqdm
import pandas as pd

MODEL_PATHS = {
    101: "./best_model_101.npz", 
    102: "./best_model_102.npz",
    103: "./best_model_103.npz",
    104: "./best_model_104.npz",
    105: "./best_model_105.npz"
}

TEST_BASE_SEED = 106
TEST_POOL_SIZE = 100
MAX_STEPS = 500

# Set environment variables for performance
os.environ.setdefault("OMP_NUM_THREADS", "1")
os.environ.setdefault("MKL_NUM_THREADS", "1")
os.environ.setdefault("KMP_DUPLICATE_LIB_OK", "TRUE")

# --- Definitions (Copied from Training Source) ---

class FixedNNPolicy(nn.Module):
    def __init__(self):
        super().__init__()
        # Acrobot: Input 8 (from your code), Output 3 (Discrete Actions)
        self.net = nn.Linear(8, 3, bias=True)
        
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.net(x)

def set_weights_vector(m: nn.Module, vec: np.ndarray):
    offset = 0
    with torch.no_grad():
        for p in m.parameters():
            n = p.numel()
            p.data.copy_(torch.from_numpy(vec[offset:offset+n]).view_as(p))
            offset += n

class RPCClient:
    def __init__(self, host, port, authkey="acrobot-rpc"):
        self.address = (host, port)
        self.authkey = authkey.encode("utf-8") if isinstance(authkey, str) else authkey
        self.conn: Optional[Client] = None
    def __enter__(self):
        try:
            self.conn = Client(self.address, authkey=self.authkey)
            return self
        except Exception as e:
            raise e
    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.conn: self.conn.close()
    def reset(self):
        self.conn.send(("reset", None)); self.conn.recv()
    def infer(self, frame_bgr):
        self.conn.send(("infer", frame_bgr)); ok, res = self.conn.recv(); return res if ok else None

# --- Evaluation Logic ---

def generate_test_seeds(base_seed: int, count: int) -> List[int]:
    print(f"Generating {count} test seeds from base seed {base_seed}...")
    g = np.random.default_rng(base_seed)
    pool = g.integers(low=0, high=2**31-1, size=count, dtype=np.int32).tolist()
    return pool

def run_single_episode(args):
    agent_id, weights, env_seed, rpc_host, rpc_port, authkey = args
    
    model = FixedNNPolicy()
    set_weights_vector(model, weights)
    
    total_reward = 0.0
    try:
        env = gym.make("Acrobot-v1", render_mode="rgb_array")
        obs, _ = env.reset(seed=int(env_seed))
        last_valid_state = np.zeros(8, dtype=np.float32)
        with RPCClient(rpc_host, rpc_port, authkey) as rpc:
            rpc.reset()
            for _ in range(MAX_STEPS):
                frame = env.render()
                if frame is None: break
                frame_bgr = frame[..., ::-1].copy()
                state = rpc.infer(frame_bgr)
                
                if state is None: state = last_valid_state
                else: last_valid_state = state
                s = torch.tensor(state, dtype=torch.float32)
                with torch.no_grad():
                    act = int(torch.argmax(model(s)).item())
                
                obs, reward, done, truncated, info = env.step(act)
                total_reward += reward
                
                if done or truncated: break
        
        env.close()
        return {
            "Agent_Source_Seed": str(agent_id),
            "Test_Env_Seed": env_seed,
            "Reward": total_reward
        }
        
    except Exception as e:
        print(f"Error on Agent {agent_id} / Seed {env_seed}: {e}")
        return {
            "Agent_Source_Seed": str(agent_id),
            "Test_Env_Seed": env_seed,
            "Reward": -500.0
        }

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--rpc-host", default="127.0.0.1")
    parser.add_argument("--rpc-port", type=int, default=6000)
    parser.add_argument("--authkey", default="acrobot-rpc")
    parser.add_argument("--processes", type=int, default=16)
    parser.add_argument("--outdir", default="evaluation_results_acrobot")
    args = parser.parse_args()

    os.makedirs(args.outdir, exist_ok=True)

    test_seeds = generate_test_seeds(TEST_BASE_SEED, TEST_POOL_SIZE)
   
    tasks = []
    print(f"\nLoading models and preparing tasks...")
    
    models_loaded = 0
    for agent_seed, model_path in MODEL_PATHS.items():
        if "path/to" in model_path: 
            print(f"[Skip] Placeholder path detected for Agent {agent_seed}")
            continue

        if not os.path.exists(model_path):
            print(f"[Warning] Model file not found: {model_path}. Skipping.")
            continue
            
        try:
            data = np.load(model_path)
            weights = data['weights']
            print(f" - Loaded Agent {agent_seed} from {model_path}")
            models_loaded += 1
            
            for env_seed in test_seeds:
                tasks.append((agent_seed, weights, env_seed, args.rpc_host, args.rpc_port, args.authkey))
                
        except Exception as e:
            print(f"[Error] Failed to load {model_path}: {e}")

    if models_loaded == 0:
        print("\n[Error] No models loaded! Please check MODEL_PATHS in the script.")
        return

    total_tasks = len(tasks)
    print(f"\nStarting Evaluation: {total_tasks} total episodes ({models_loaded} Agents * {TEST_POOL_SIZE} Envs)")
    print(f"Using {args.processes} processes.")

    results = []
    with mp.Pool(processes=args.processes) as pool:
        for res in tqdm(pool.imap_unordered(run_single_episode, tasks), total=total_tasks, desc="Evaluating"):
            results.append(res)

    df = pd.DataFrame(results)

    csv_path = os.path.join(args.outdir, "acrobot_eval_data_seed106.csv")
    df.to_csv(csv_path, index=False)
    print(f"\nRaw data saved to: {csv_path}")

    summary = df.groupby("Agent_Source_Seed")["Reward"].agg(['mean', 'std', 'min', 'max'])
    print("\n=== Summary Statistics ===")
    print(summary)
    
    print("\nReady for plotting. You can now use the CSV file for visualization.")

if __name__ == "__main__":
    main()